	worldW              = 5000
	worldD              = 5000
	maxY                = 100
	maxPlayers          = 8
	editChunk           = 48000
	blockWater          = 14
	blockLava           = 22
	maxHealth           = 20
	pvpReach            = 4.2
	pvpDamage           = 4
	defaultPvpKnockback = 1.0
	dayLength           = 20 * 60.0 // seconds per in-game day
