// ---------------------------------------------------------------- helpers

func isInt(f float64) bool { return f == math.Trunc(f) && math.Abs(f) < 1e9 }

func voxelIndex(x, y, z int) uint32 {
	return (uint32(z)*worldW+uint32(x))*maxY + uint32(y)
}

func cleanName(s string) string {
	var b strings.Builder
	for _, r := range s {
		if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') ||
			r == '_' || r == '-' || r == ' ' {
			b.WriteRune(r)
		}
	}
	out := strings.TrimSpace(b.String())
	if len(out) > 16 {
		out = strings.TrimSpace(out[:16])
	}
	return out
}

func rayAABB(ox, oy, oz, dx, dy, dz float64, lo, hi [3]float64, maxT float64) float64 {
	o := [3]float64{ox, oy, oz}
	d := [3]float64{dx, dy, dz}
	tmin, tmax := 0.0, maxT
	for i := 0; i < 3; i++ {
		if math.Abs(d[i]) < 1e-9 {
			if o[i] < lo[i] || o[i] > hi[i] {
				return -1
			}
			continue
		}
		t1 := (lo[i] - o[i]) / d[i]
		t2 := (hi[i] - o[i]) / d[i]
		if t1 > t2 {
			t1, t2 = t2, t1
		}
		if t1 > tmin {
			tmin = t1
		}
		if t2 < tmax {
			tmax = t2
		}
		if tmin > tmax {
			return -1
		}
	}
	return tmin
}

// ---------------------------------------------------------------- sending (caller holds s.mu)

func (s *server) sendRaw(p *player, b []byte) {
	select {
	case p.send <- b:
	default:
		go p.conn.Close() // client can't keep up: drop it
	}
}

func (s *server) sendTo(p *player, v any) {
	b, err := json.Marshal(v)
	if err != nil {
		return
	}
	s.sendRaw(p, b)
}

func (s *server) broadcast(v any, except *player) {
	b, err := json.Marshal(v)
	if err != nil {
		return
	}
	for _, q := range s.players {
		if q != except {
			s.sendRaw(q, b)
		}
	}
}

func (s *server) sys(p *player, text string) {
	s.sendTo(p, M{"t": "c", "n": "Server", "m": text})
}

func (s *server) reject(p *player, msg string) {
	s.sendTo(p, M{"t": "err", "m": msg})
	go func() {
		time.Sleep(400 * time.Millisecond)
		p.conn.Close()
	}()
}

// ---------------------------------------------------------------- join / leave

func (s *server) uniqueName(n string, id int) string {
	if n == "" {
		n = "Player" + strconv.Itoa(id)
	}
	used := map[string]bool{}
	for _, q := range s.players {
		used[q.name] = true
	}
	out := n
	for i := 2; used[out]; i++ {
		base := n
		if len(base) > 13 {
			base = base[:13]
		}
		out = base + strconv.Itoa(i)
	}
	return out
}

func (s *server) encodeEdits() []byte { return encodeVoxels(s.edits) }

func encodeVoxels(m map[uint32]uint8) []byte {
	buf := make([]byte, 0, len(m)*5)
	var tmp [4]byte
	for idx, v := range m {
		binary.LittleEndian.PutUint32(tmp[:], idx)
		buf = append(buf, tmp[:]...)
		buf = append(buf, v)
	}
	return buf
}

func (s *server) join(p *player, m *inMsg) {
	if p.joined {
		return
	}
	if m.V != netVersion {
		s.reject(p, "Version mismatch - reload the page")
		return
	}
	if len(s.players) >= maxPlayers {
		s.reject(p, "Room is full")
		return
	}
	s.nextID++
	p.id = s.nextID
	p.name = s.uniqueName(cleanName(m.Name), p.id)
	p.health = maxHealth
	p.op = !s.hasOp()
	if s.spawn != nil {
		p.x, p.y, p.z = s.spawn[0], s.spawn[1], s.spawn[2]
	}
	if s.simID == 0 {
		s.simID = p.id
	}
	for _, drop := range s.drops {
		if s.players[drop.ownerID] == nil {
			drop.ownerID = p.id
		}
	}

	plist := []M{}
	for _, q := range s.players {
		plist = append(plist, M{"id": q.id, "name": q.name, "x": q.x, "y": q.y, "z": q.z,
			"yaw": q.yaw, "pitch": q.pitch, "health": q.health, "dead": q.dead})
	}
	eb := s.encodeEdits()
	nChunks := (len(eb) + editChunk - 1) / editChunk
	fb := encodeVoxels(s.fluid)
	nFluidChunks := (len(fb) + editChunk - 1) / editChunk
	welcome := M{
		"t": "welcome", "id": p.id, "seed": s.seed, "mode": s.mode, "time": s.wtime,
		"pvp": s.pvp, "pvpKnockback": s.pvpKnockback, "op": p.op,
		"players": plist, "editBytes": len(eb), "chunks": nChunks,
		"fluidBytes": len(fb), "fluidChunks": nFluidChunks,
		"sim": s.simID == p.id, "spawn": nil,
	}
	if s.spawn != nil {
		welcome["spawn"] = M{"x": s.spawn[0], "y": s.spawn[1], "z": s.spawn[2]}
	}
	s.sendTo(p, welcome)
	for i := 0; i < nChunks; i++ {
		end := (i + 1) * editChunk
		if end > len(eb) {
			end = len(eb)
		}
		s.sendTo(p, M{"t": "edits", "i": i, "d": base64.StdEncoding.EncodeToString(eb[i*editChunk : end])})
	}
	for i := 0; i < nFluidChunks; i++ {
		end := (i + 1) * editChunk
		if end > len(fb) {
			end = len(fb)
		}
		s.sendTo(p, M{"t": "fluid", "i": i, "d": base64.StdEncoding.EncodeToString(fb[i*editChunk : end])})
	}
	for _, drop := range s.drops {
		s.sendTo(p, dropMessage("drop-add", drop))
	}
	for _, projectile := range s.projectiles {
		s.sendTo(p, projectileMessage("projectile-add", projectile))
	}

	p.joined = true
	s.players[p.id] = p
	if p.op {
		s.sys(p, "You are a server operator. Use /help to see commands.")
	}
	s.broadcast(M{"t": "j", "id": p.id, "name": p.name}, p)
	log.Printf("+ %s joined (id %d, %d players)", p.name, p.id, len(s.players))
}

func (s *server) drop(p *player) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if !p.joined {
		return
	}
	p.joined = false
	delete(s.players, p.id)
	s.broadcast(M{"t": "l", "id": p.id, "name": p.name}, nil)
	var nextOwner int
	for id := range s.players {
		if nextOwner == 0 || id < nextOwner {
			nextOwner = id
		}
	}
	for _, drop := range s.drops {
		if drop.ownerID == p.id && nextOwner != 0 {
			drop.ownerID = nextOwner
			s.broadcast(dropMessage("drop-update", drop), nil)
		}
	}
	for id, projectile := range s.projectiles {
		if projectile.ownerID == p.id {
			delete(s.projectiles, id)
			s.broadcast(M{"t": "projectile-remove", "projectileId": id}, nil)
		}
	}
	log.Printf("- %s left (%d players)", p.name, len(s.players))
	if s.simID == p.id {
		s.simID = 0
		for id := range s.players {
			if s.simID == 0 || id < s.simID {
				s.simID = id
			}
		}
		if q := s.players[s.simID]; q != nil {
			s.sendTo(q, M{"t": "sim", "on": true})
		}
	}
	if p.op {
		s.promoteOperator()
	}
	s.dirty = true
	if len(s.players) == 0 {
		go s.save(true)
	}
}

// ---------------------------------------------------------------- message handling

func (s *server) handle(p *player, m *inMsg) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if m.T == "hello" {
		s.join(p, m)
		return
	}
	if !p.joined {
		return
	}
	switch m.T {
	case "p":
		s.onPos(p, m)
	case "b":
		s.onBlock(p, m)
	case "drop-spawn":
		s.onDropSpawn(p, m)
	case "drop-update":
		s.onDropUpdate(p, m)
	case "drop-remove":
		s.onDropRemove(p, m)
	case "drop-pick":
		s.onDropPick(p, m)
	case "projectile-spawn":
		s.onProjectileSpawn(p, m)
	case "projectile-update":
		s.onProjectileUpdate(p, m)
	case "projectile-remove":
		s.onProjectileRemove(p, m)
	case "projectile-hit":
		s.onProjectileHit(p, m)
	case "c":
		s.onChat(p, m)
	case "spawn":
		if s.spawn == nil && math.Abs(m.X) < 1e6 && math.Abs(m.Y) < 1e6 && math.Abs(m.Z) < 1e6 {
			s.spawn = &[3]float64{m.X, m.Y, m.Z}
			s.dirty = true
		}
	case "pvp-attack":
		if isInt(m.ID) {
			s.pvpAttack(p, int(m.ID), m)
		}
	case "pvp-heal":
		s.pvpHeal(p, m.Heal)
	case "pvp-damage":
		s.pvpDamage(p, m.Damage)
	case "pvp-time":
		if !s.isOp(p) {
			s.sys(p, "Only server operators can change the shared world time.")
		} else if !math.IsNaN(m.Time) && !math.IsInf(m.Time, 0) && m.Time >= 0 && m.Time < 24 {
			now := time.Now()
			if now.Sub(p.lastWorldTimeChange) < 500*time.Millisecond {
				s.sys(p, "World time can only be adjusted twice per second.")
			} else {
				p.lastWorldTimeChange = now
				s.setWorldTime(m.Time / 24)
			}
		}
	case "pvp-dead":
		if s.pvp {
			p.dead, p.health = true, 0
			s.broadcast(M{"t": "pvp-health", "id": p.id, "health": 0, "dead": true, "amount": 0}, nil)
		}
	case "pvp-respawn":
		s.pvpRespawn(p)
	}
}

func (s *server) onPos(p *player, m *inMsg) {
	if math.Abs(m.X) > 1e6 || math.Abs(m.Y) > 1e6 || math.Abs(m.Z) > 1e6 {
		return
	}
	if p.dead {
		if s.pvp {
			return
		}
		p.dead, p.health = false, maxHealth
		s.broadcast(M{"t": "pvp-respawn", "id": p.id, "x": m.X, "y": m.Y, "z": m.Z}, p)
	}
	p.x, p.y, p.z, p.yaw, p.pitch = m.X, m.Y, m.Z, m.Yaw, m.Pitch
	s.broadcast(M{"t": "p", "id": p.id, "x": m.X, "y": m.Y, "z": m.Z, "yaw": m.Yaw, "pitch": m.Pitch}, p)
}

func (s *server) onBlock(p *player, m *inMsg) {
	if !isInt(m.X) || !isInt(m.Y) || !isInt(m.Z) || !isInt(m.ID) {
		return
	}
	x, y, z, id := int(m.X), int(m.Y), int(m.Z), int(m.ID)
	if x < 0 || x >= worldW || z < 0 || z >= worldD || y < 1 || y >= maxY { // y=0 is bedrock
		return
	}
	// 9 = bedrock, 100-118 = built-in items; chunk data is one byte, so blocks are 0-255
	if id < 0 || id > 255 || id == 9 || (id >= 100 && id <= 118) {
		return
	}
	lv := 0
	if (id == blockWater || id == blockLava) && isInt(m.Lv) && m.Lv > 0 && m.Lv < 16 {
		lv = int(m.Lv)
	}
	idx := voxelIndex(x, y, z)
	if old, ok := s.edits[idx]; ok && int(old) == id && int(s.fluid[idx]) == lv {
		return
	}
	s.edits[idx] = uint8(id)
	if s.fluid == nil {
		s.fluid = map[uint32]uint8{}
	}
	if lv > 0 {
		s.fluid[idx] = uint8(lv)
	} else {
		delete(s.fluid, idx)
	}
	s.dirty = true
	out := M{"t": "b", "x": x, "y": y, "z": z, "id": id}
	if lv > 0 {
		out["lv"] = lv
	}
	s.broadcast(out, p)
}

func dropMessage(messageType string, drop *worldDrop) M {
	return M{
		"t": messageType, "dropId": drop.id, "owner": drop.ownerID, "clientId": drop.clientID,
		"item": drop.item, "count": drop.count, "x": drop.x, "y": drop.y, "z": drop.z,
		"vx": drop.vx, "vy": drop.vy, "vz": drop.vz, "age": drop.age, "settled": drop.settled,
	}
}

func validDropPosition(x, y, z float64) bool {
	return !math.IsNaN(x) && !math.IsInf(x, 0) && !math.IsNaN(y) && !math.IsInf(y, 0) &&
		!math.IsNaN(z) && !math.IsInf(z, 0) &&
		x >= 0 && x < worldW && y >= -12 && y < maxY+32 && z >= 0 && z < worldD
}

func (s *server) onDropSpawn(p *player, m *inMsg) {
	if m.ClientID == "" || len(m.ClientID) > 64 || m.Item < 1 || m.Item > 65535 ||
		m.Count < 1 || m.Count > 64 || !validDropPosition(m.X, m.Y, m.Z) ||
		!isFinite(m.VX) || !isFinite(m.VY) || !isFinite(m.VZ) ||
		math.Abs(m.VX) > 40 || math.Abs(m.VY) > 40 || math.Abs(m.VZ) > 40 {
		return
	}
	if math.Hypot(math.Hypot(m.X-p.x, m.Z-p.z), m.Y-p.y) > 16 {
		return
	}
	if s.drops == nil {
		s.drops = make(map[uint64]*worldDrop)
	}
	if len(s.drops) >= 512 {
		s.sendTo(p, M{"t": "drop-denied", "clientId": m.ClientID, "reason": "The shared world has reached its dropped-item limit."})
		return
	}
	for _, existing := range s.drops {
		if existing.ownerID == p.id && existing.clientID == m.ClientID {
			s.sendTo(p, dropMessage("drop-add", existing))
			return
		}
	}
	s.nextDropID++
	drop := &worldDrop{
		id: s.nextDropID, ownerID: p.id, clientID: m.ClientID,
		item: m.Item, count: m.Count, x: m.X, y: m.Y, z: m.Z,
		vx: m.VX, vy: m.VY, vz: m.VZ, age: math.Max(0, m.Age), settled: m.Settled,
		lastUpdate: time.Now(),
	}
	s.drops[drop.id] = drop
	s.broadcast(dropMessage("drop-add", drop), nil)
}

func (s *server) onDropUpdate(p *player, m *inMsg) {
	drop := s.drops[m.DropID]
	if drop == nil || drop.ownerID != p.id || !validDropPosition(m.X, m.Y, m.Z) ||
		!isFinite(m.VX) || !isFinite(m.VY) || !isFinite(m.VZ) ||
		math.Abs(m.VX) > 40 || math.Abs(m.VY) > 40 || math.Abs(m.VZ) > 40 ||
		!isFinite(m.Age) || m.Age < 0 || m.Age > 86400 {
		return
	}
	now := time.Now()
	if now.Sub(drop.lastUpdate) < 75*time.Millisecond {
		return
	}
	drop.x, drop.y, drop.z = m.X, m.Y, m.Z
	drop.vx, drop.vy, drop.vz = m.VX, m.VY, m.VZ
	drop.age, drop.settled = m.Age, m.Settled
	drop.lastUpdate = now
	s.broadcast(dropMessage("drop-update", drop), p)
}

func (s *server) onDropRemove(p *player, m *inMsg) {
	drop := s.drops[m.DropID]
	if drop == nil || drop.ownerID != p.id {
		return
	}
	delete(s.drops, drop.id)
	s.broadcast(M{"t": "drop-remove", "dropId": drop.id}, nil)
}

func (s *server) onDropPick(p *player, m *inMsg) {
	drop := s.drops[m.DropID]
	if drop == nil || drop.age < 0.6 || m.Count < 1 || m.Count > drop.count ||
		math.Hypot(math.Hypot(drop.x-p.x, drop.z-p.z), drop.y-(p.y+0.9)) > 3.5 {
		s.sendTo(p, M{"t": "drop-pick-denied", "dropId": m.DropID})
		return
	}
	drop.count -= m.Count
	if drop.count == 0 {
		delete(s.drops, drop.id)
		s.broadcast(M{"t": "drop-remove", "dropId": drop.id}, nil)
	} else {
		s.broadcast(dropMessage("drop-update", drop), nil)
	}
	s.sendTo(p, M{"t": "drop-picked", "dropId": drop.id, "item": drop.item, "count": m.Count})
}

func isFinite(value float64) bool {
	return !math.IsNaN(value) && !math.IsInf(value, 0)
}

func projectileMessage(messageType string, projectile *worldProjectile) M {
	return M{
		"t": messageType, "projectileId": projectile.id, "owner": projectile.ownerID,
		"clientId": projectile.clientID, "packId": projectile.packID, "projectileItem": projectile.itemID,
		"hookScope": projectile.hookScope, "hookKey": projectile.hookKey,
		"x": projectile.x, "y": projectile.y, "z": projectile.z,
		"dx": projectile.dx, "dy": projectile.dy, "dz": projectile.dz,
		"speed": projectile.speed, "lifetime": projectile.lifetime,
		"projectileDamage": projectile.damage, "age": projectile.age,
	}
}

func (s *server) onProjectileSpawn(p *player, m *inMsg) {
	directionLength := math.Sqrt(m.DX*m.DX + m.DY*m.DY + m.DZ*m.DZ)
	if m.ClientID == "" || len(m.ClientID) > 64 ||
		!sharedPackIDPattern.MatchString(m.PackID) || m.ProjectileItem < 1 || m.ProjectileItem > 65535 ||
		(m.HookScope != "item" && m.HookScope != "feature") ||
		!sharedHookKeyPattern.MatchString(m.HookKey) ||
		!validDropPosition(m.X, m.Y, m.Z) ||
		!isFinite(directionLength) || directionLength < 0.99 || directionLength > 1.01 ||
		!isFinite(m.Speed) || m.Speed < 0.1 || m.Speed > 80 ||
		!isFinite(m.Lifetime) || m.Lifetime < 0.1 || m.Lifetime > 30 ||
		!isFinite(m.ProjectileDamage) || m.ProjectileDamage < 0 || m.ProjectileDamage > 20 {
		return
	}
	if math.Hypot(math.Hypot(m.X-p.x, m.Z-p.z), m.Y-(p.y+1.5)) > 16 {
		return
	}
	if s.projectiles == nil {
		s.projectiles = make(map[uint64]*worldProjectile)
	}
	if len(s.projectiles) >= 256 {
		s.sendTo(p, M{"t": "projectile-denied", "clientId": m.ClientID})
		return
	}
	for _, existing := range s.projectiles {
		if existing.ownerID == p.id && existing.clientID == m.ClientID {
			s.sendTo(p, projectileMessage("projectile-add", existing))
			return
		}
	}
	s.nextProjectileID++
	projectile := &worldProjectile{
		id: s.nextProjectileID, ownerID: p.id, clientID: m.ClientID,
		packID: m.PackID, itemID: m.ProjectileItem, hookScope: m.HookScope, hookKey: m.HookKey,
		x: m.X, y: m.Y, z: m.Z, dx: m.DX / directionLength, dy: m.DY / directionLength, dz: m.DZ / directionLength,
		speed: m.Speed, lifetime: m.Lifetime, damage: m.ProjectileDamage,
		lastUpdate: time.Now(),
	}
	s.projectiles[projectile.id] = projectile
	s.broadcast(projectileMessage("projectile-add", projectile), nil)
}

func (s *server) onProjectileUpdate(p *player, m *inMsg) {
	projectile := s.projectiles[m.ProjectileID]
	if projectile == nil || projectile.ownerID != p.id || !validDropPosition(m.X, m.Y, m.Z) ||
		!isFinite(m.Age) || m.Age < 0 || m.Age > projectile.lifetime {
		return
	}
	now := time.Now()
	if now.Sub(projectile.lastUpdate) < 75*time.Millisecond {
		return
	}
	projectile.x, projectile.y, projectile.z = m.X, m.Y, m.Z
	projectile.age = m.Age
	projectile.lastUpdate = now
	s.broadcast(M{
		"t": "projectile-update", "projectileId": projectile.id,
		"x": projectile.x, "y": projectile.y, "z": projectile.z, "age": projectile.age,
	}, p)
}

func (s *server) onProjectileRemove(p *player, m *inMsg) {
	projectile := s.projectiles[m.ProjectileID]
	if projectile == nil && m.ClientID != "" {
		for _, candidate := range s.projectiles {
			if candidate.ownerID == p.id && candidate.clientID == m.ClientID {
				projectile = candidate
				break
			}
		}
	}
	if projectile == nil || projectile.ownerID != p.id {
		return
	}
	delete(s.projectiles, projectile.id)
	s.broadcast(M{"t": "projectile-remove", "projectileId": projectile.id}, nil)
}

func (s *server) onProjectileHit(p *player, m *inMsg) {
	projectile := s.projectiles[m.ProjectileID]
	if projectile == nil && m.ClientID != "" {
		for _, candidate := range s.projectiles {
			if candidate.ownerID == p.id && candidate.clientID == m.ClientID {
				projectile = candidate
				break
			}
		}
	}
	target := s.players[m.TargetID]
	if !s.pvp || p.dead || projectile == nil || projectile.ownerID != p.id ||
		target == nil || target.id == p.id || target.dead ||
		!isFinite(m.HitX) || !isFinite(m.HitY) || !isFinite(m.HitZ) ||
		projectile.damage <= 0 || !isFinite(projectile.damage) {
		return
	}

	// The impact must be near the projectile's recent path and inside the
	// target's server-reported bounds, allowing for update and movement delay.
	dx, dy, dz := m.HitX-projectile.x, m.HitY-projectile.y, m.HitZ-projectile.z
	alongPath := dx*projectile.dx + dy*projectile.dy + dz*projectile.dz
	pathDistance := math.Sqrt(dx*dx + dy*dy + dz*dz)
	maxTravel := projectile.speed*0.5 + 1.5
	if alongPath < -0.75 || pathDistance > maxTravel ||
		math.Sqrt(math.Max(0, pathDistance*pathDistance-alongPath*alongPath)) > 1.25 ||
		m.HitX < target.x-0.55 || m.HitX > target.x+0.55 ||
		m.HitY < target.y-0.2 || m.HitY > target.y+2.0 ||
		m.HitZ < target.z-0.55 || m.HitZ > target.z+0.55 {
		return
	}

	damage := int(math.Round(math.Max(1, math.Min(maxHealth, projectile.damage))))
	target.health = max(0, target.health-damage)
	target.dead = target.health == 0
	knockX, knockZ := target.x-p.x, target.z-p.z
	length := math.Hypot(knockX, knockZ)
	if length == 0 {
		length = 1
	}
	knockX, knockZ = knockX/length, knockZ/length
	healthUpdate := M{
		"t": "pvp-health", "id": target.id, "amount": damage, "by": p.name,
		"health": target.health, "dead": target.dead,
		"knockX": knockX, "knockZ": knockZ, "knockback": s.pvpKnockback,
	}
	s.sendTo(target, healthUpdate)
	s.broadcast(healthUpdate, target)
	delete(s.projectiles, projectile.id)
	s.broadcast(M{"t": "projectile-remove", "projectileId": projectile.id}, nil)
}

func (s *server) isOp(p *player) bool {
	return p != nil && p.op
}

func (s *server) hasOp() bool {
	for _, q := range s.players {
		if q.op {
			return true
		}
	}
	return false
}

func (s *server) promoteOperator() {
	if s.hasOp() {
		return
	}
	var next *player
	for _, q := range s.players {
		if next == nil || q.id < next.id {
			next = q
		}
	}
	if next != nil {
		next.op = true
		s.sendTo(next, M{"t": "op", "op": true})
		s.sys(next, "You are now a server operator. Use /help to see commands.")
	}
}

func (s *server) findPlayer(name string) *player {
	name = strings.TrimSpace(name)
	if name == "" || strings.EqualFold(name, "@s") || strings.EqualFold(name, "self") {
		return nil
	}
	for _, q := range s.players {
		if strings.EqualFold(q.name, name) {
			return q
		}
	}
	return nil
}

func (s *server) setPvP(enabled bool) {
	s.pvp = enabled
	for _, q := range s.players {
		q.dead, q.health = false, maxHealth
	}
	s.broadcast(M{"t": "pvp-mode", "enabled": s.pvp}, nil)
}

func (s *server) setGameMode(mode string) {
	s.mode = mode
	s.dirty = true
	s.broadcast(M{"t": "gamemode", "mode": mode}, nil)
}

func (s *server) setWorldTime(value float64) {
	s.wtime = math.Mod(value, 1)
	if s.wtime < 0 {
		s.wtime++
	}
	s.dirty = true
	s.broadcast(M{"t": "tm", "time": s.wtime}, nil)
}

func (s *server) setPvPKnockback(value float64) {
	s.pvpKnockback = math.Max(0, math.Min(2, value))
	s.dirty = true
	s.broadcast(M{"t": "pvp-knockback", "value": s.pvpKnockback}, nil)
}

func (s *server) onChat(p *player, m *inMsg) {
	r := []rune(strings.TrimSpace(m.M))
	if len(r) > 120 {
		r = r[:120]
	}
	text := strings.TrimSpace(string(r))
	if text == "" {
		return
	}
	if strings.HasPrefix(text, "/") {
		s.command(p, text)
		return
	}
	log.Printf("<%s> %s", p.name, text)
	s.broadcast(M{"t": "c", "n": p.name, "m": text}, nil)
}

func (s *server) command(p *player, text string) {
	f := strings.Fields(strings.TrimSpace(text))
	if len(f) == 0 {
		return
	}
	cmd := strings.ToLower(f[0])
	switch cmd {
	case "/help", "/commands":
		s.sys(p, "Commands: /list, /pvp [on|off], /knockback <0-200>, /gamemode <survival|creative>, /time [query|set <time>|day|night|noon|midnight], /give [player] <item|id> [amount], /op [player], /deop <player>, /tp <player>.")
	case "/list":
		names := make([]string, 0, len(s.players))
		for _, q := range s.players {
			suffix := ""
			if q.op {
				suffix = " (op)"
			}
			names = append(names, q.name+suffix)
		}
		s.sys(p, fmt.Sprintf("Players (%d/%d): %s", len(names), maxPlayers, strings.Join(names, ", ")))
	case "/op":
		if !s.isOp(p) {
			s.sys(p, "Only an operator can use this command.")
			return
		}
		if len(f) == 1 {
			s.sys(p, "You are "+map[bool]string{true: "an operator.", false: "not an operator."}[p.op])
			return
		}
		target := s.findPlayer(strings.Join(f[1:], " "))
		if target == nil {
			s.sys(p, "Player not found. Usage: /op <player>")
			return
		}
		if target.op {
			s.sys(p, target.name+" is already an operator.")
			return
		}
		target.op = true
		s.sendTo(target, M{"t": "op", "op": true})
		s.sys(target, "You are now a server operator.")
		s.broadcast(M{"t": "c", "n": "Server", "m": target.name + " is now an operator."}, nil)
	case "/deop":
		if !s.isOp(p) {
			s.sys(p, "Only an operator can use this command.")
			return
		}
		target := s.findPlayer(strings.Join(f[1:], " "))
		if target == nil {
			s.sys(p, "Player not found. Usage: /deop <player>")
			return
		}
		if !target.op {
			s.sys(p, target.name+" is not an operator.")
			return
		}
		opCount := 0
		for _, q := range s.players {
			if q.op {
				opCount++
			}
		}
		if target == p && opCount == 1 {
			s.sys(p, "You cannot remove the only operator.")
			return
		}
		target.op = false
		s.sendTo(target, M{"t": "op", "op": false})
		s.sys(target, "Your server operator privileges were removed.")
		s.broadcast(M{"t": "c", "n": "Server", "m": target.name + " is no longer an operator."}, nil)
	case "/pvp":
		if !s.requireOp(p) {
			return
		}
		on, valid := parseToggle(f[1:], s.pvp)
		if !valid {
			s.sys(p, "Usage: /pvp [on|off]")
			return
		}
		s.setPvP(on)
		s.dirty = true
		s.sys(p, "PvP "+toggleText(s.pvp)+".")
	case "/knockback", "/pvpknockback":
		if !s.requireOp(p) {
			return
		}
		if len(f) != 2 {
			s.sys(p, fmt.Sprintf("PvP knockback is %.0f%%. Usage: /knockback <0-200>", s.pvpKnockback*100))
			return
		}
		percent, err := strconv.ParseFloat(f[1], 64)
		if err != nil || math.IsNaN(percent) || math.IsInf(percent, 0) || percent < 0 || percent > 200 {
			s.sys(p, "Usage: /knockback <0-200> (percent)")
			return
		}
		s.setPvPKnockback(percent / 100)
		s.sys(p, fmt.Sprintf("PvP knockback set to %.0f%%.", s.pvpKnockback*100))
	case "/gamemode", "/mode", "/gmode", "/gmc", "/gms":
		if !s.requireOp(p) {
			return
		}
		mode := ""
		switch cmd {
		case "/gmc":
			mode = "creative"
		case "/gms":
			mode = "survival"
		default:
			if len(f) > 1 {
				mode = strings.ToLower(f[1])
			}
		}
		if mode != "survival" && mode != "creative" {
			s.sys(p, "Usage: /gamemode <survival|creative> (aliases: /gms, /gmc)")
			return
		}
		s.setGameMode(mode)
		s.sys(p, "Game mode set to "+mode+".")
	case "/time":
		if !s.requireOp(p) {
			return
		}
		if len(f) == 1 || strings.EqualFold(f[1], "query") {
			s.sys(p, fmt.Sprintf("World time: %s", formatWorldTime(s.wtime)))
			return
		}
		value, ok := parseWorldTime(f[1:])
		if !ok {
			s.sys(p, "Usage: /time set <HH:MM|0-23|day|night|noon|midnight>")
			return
		}
		s.setWorldTime(value)
		s.sys(p, "World time set to "+formatWorldTime(s.wtime)+".")
	case "/give":
		if !s.requireOp(p) {
			return
		}
		args := f[1:]
		target, itemAt := p, 0
		if len(args) > 0 && (args[0] == "@s" || strings.EqualFold(args[0], "self")) {
			itemAt = 1
		} else {
			for end := len(args) - 1; end > 0; end-- {
				if found := s.findPlayer(strings.Join(args[:end], " ")); found != nil {
					target, itemAt = found, end
					break
				}
			}
		}
		if itemAt >= len(args) {
			s.sys(p, "Usage: /give [player] <item-id|name> [amount]")
			return
		}
		itemArgs := args[itemAt:]
		count := 1
		if len(itemArgs) > 1 {
			if parsed, err := strconv.Atoi(itemArgs[len(itemArgs)-1]); err == nil {
				if parsed < 1 || parsed > 64 {
					s.sys(p, "Item amount must be from 1 to 64.")
					return
				}
				count = parsed
				itemArgs = itemArgs[:len(itemArgs)-1]
			}
		}
		itemID, ok := parseItemID(strings.Join(itemArgs, " "))
		if !ok {
			s.sys(p, "Unknown item. Use a built-in item name or numeric item ID.")
			return
		}
		s.sendTo(target, M{"t": "grant", "id": itemID, "count": count})
		s.sys(p, fmt.Sprintf("Gave %s %d x item %d.", target.name, count, itemID))
	case "/tp", "/teleport":
		if !s.requireOp(p) {
			return
		}
		target := s.findPlayer(strings.Join(f[1:], " "))
		if target == nil {
			s.sys(p, "Usage: /tp <online-player>")
			return
		}
		s.sendTo(p, M{"t": "teleport", "x": target.x, "y": target.y, "z": target.z})
		s.sys(p, "Teleported to "+target.name+".")
	default:
		s.sys(p, "Unknown command. Type /help for available commands.")
	}
}

func (s *server) requireOp(p *player) bool {
	if s.isOp(p) {
		return true
	}
	s.sys(p, "Only an operator can use this command.")
	return false
}

func parseToggle(args []string, current bool) (bool, bool) {
	if len(args) == 0 {
		return !current, true
	}
	if len(args) != 1 {
		return current, false
	}
	switch strings.ToLower(args[0]) {
	case "on", "true", "yes":
		return true, true
	case "off", "false", "no":
		return false, true
	default:
		return current, false
	}
}

func toggleText(enabled bool) string {
	if enabled {
		return "enabled"
	}
	return "disabled"
}

func parseWorldTime(args []string) (float64, bool) {
	if len(args) == 0 || (len(args) == 1 && strings.EqualFold(args[0], "query")) {
		return 0, false
	}
	if len(args) > 1 && !strings.EqualFold(args[0], "set") {
		return 0, false
	}
	value := args[len(args)-1]
	switch strings.ToLower(value) {
	case "day", "sunrise":
		return 0.25, true
	case "noon":
		return 0.5, true
	case "night", "sunset":
		return 0.75, true
	case "midnight":
		return 0, true
	}
	if strings.Contains(value, ":") {
		parsed, err := time.Parse("15:04", value)
		if err != nil {
			return 0, false
		}
		minutes := parsed.Hour()*60 + parsed.Minute()
		return float64(minutes) / (24 * 60), true
	}
	hour, err := strconv.ParseFloat(value, 64)
	if err != nil || math.IsNaN(hour) || math.IsInf(hour, 0) || hour < 0 || hour >= 24 {
		return 0, false
	}
	return hour / 24, true
}

func formatWorldTime(value float64) string {
	minutes := int(math.Mod(value, 1) * 24 * 60)
	return fmt.Sprintf("%02d:%02d", minutes/60, minutes%60)
}

func parseItemID(value string) (int, bool) {
	if id, err := strconv.Atoi(value); err == nil {
		return id, id > 0 && id <= 65535
	}
	item := strings.ToLower(strings.ReplaceAll(value, "_", " "))
	itemIDs := map[string]int{
		"grass": 1, "dirt": 2, "stone": 3, "sand": 4, "log": 5, "leaves": 6,
		"planks": 7, "brick": 8, "bedrock": 9, "sandstone": 10, "stone bricks": 11,
		"crafting table": 12, "door": 13, "water": 14, "iron ore": 15, "gold ore": 16,
		"diamond ore": 17, "ruby ore": 18, "emerald ore": 19, "furnace": 20, "coal ore": 21,
		"lava": 22, "mycelium": 23, "mushroom stem": 24, "red mushroom cap": 25,
		"brown mushroom cap": 26, "red mushroom": 27, "brown mushroom": 28, "tall grass": 29,
		"gravel": 99, "stick": 100, "wood pickaxe": 101, "stone pickaxe": 102,
		"iron pickaxe": 103, "gold pickaxe": 104, "diamond pickaxe": 105, "fish": 106,
		"coal": 107, "raw iron": 108, "raw gold": 109, "iron ingot": 110,
		"gold ingot": 111, "diamond": 112, "ruby": 113, "emerald": 114, "torch": 115,
		"water bucket": 116, "lava bucket": 117, "bucket": 118,
	}
	id, ok := itemIDs[item]
	return id, ok
}

// ---------------------------------------------------------------- PvP

func clampF(v, lo, hi, def float64) float64 {
	if v == 0 || math.IsNaN(v) {
		return def
	}
	return math.Max(lo, math.Min(hi, v))
}

func (s *server) pvpAttack(a *player, targetID int, m *inMsg) {
	if !s.pvp || a.dead || targetID == a.id {
		return
	}
	t := s.players[targetID]
	now := time.Now()
	if t == nil || t.dead || now.Sub(a.lastAttack) < time.Duration(clampF(m.Cd, 0.1, 5, 0.5)*float64(time.Second)) {
		return
	}
	cp := math.Cos(a.pitch)
	dx, dy, dz := -math.Sin(a.yaw)*cp, math.Sin(a.pitch), -math.Cos(a.yaw)*cp
	hit := rayAABB(a.x, a.y+1.5, a.z, dx, dy, dz,
		[3]float64{t.x - 0.3, t.y, t.z - 0.3}, [3]float64{t.x + 0.3, t.y + 1.8, t.z + 0.3}, clampF(m.Reach, 0.5, 8, pvpReach))
	if hit < 0 {
		return
	}
	a.lastAttack = now
	kx, kz := t.x-a.x, t.z-a.z
	l := math.Hypot(kx, kz)
	if l == 0 {
		l = 1
	}
	kx, kz = kx/l, kz/l
	damage := int(math.Round(clampF(m.Dmg, 1, maxHealth, pvpDamage)))
	knockbackMultiplier := 1.0
	if m.KB != nil && !math.IsNaN(*m.KB) && !math.IsInf(*m.KB, 0) {
		knockbackMultiplier = math.Max(0, math.Min(3, *m.KB))
	}
	t.health -= damage
	if t.health < 0 {
		t.health = 0
	}
	t.dead = t.health <= 0
	upd := func(amount int) M {
		return M{"t": "pvp-health", "id": t.id, "amount": amount, "by": a.name,
			"health": t.health, "dead": t.dead, "knockX": kx, "knockZ": kz,
			"knockback": s.pvpKnockback * knockbackMultiplier}
	}
	s.sendTo(t, upd(damage))
	s.broadcast(upd(0), t)
}

func (s *server) pvpHeal(p *player, amount float64) {
	if !s.pvp || p.dead || math.IsNaN(amount) || math.IsInf(amount, 0) || amount < 1 || amount > 4 {
		return
	}
	now := time.Now()
	if now.Sub(p.lastHealthEffect) < time.Second || p.health >= maxHealth {
		return
	}
	p.lastHealthEffect = now
	p.health = min(maxHealth, p.health+int(math.Round(amount)))
	s.sendTo(p, M{"t": "pvp-heal", "id": p.id, "health": p.health})
}

func (s *server) pvpDamage(p *player, amount float64) {
	if !s.pvp || p.dead || math.IsNaN(amount) || math.IsInf(amount, 0) || amount < 1 || amount > 4 {
		return
	}
	now := time.Now()
	if now.Sub(p.lastHealthEffect) < time.Second {
		return
	}
	p.lastHealthEffect = now
	damage := int(math.Round(amount))
	p.health = max(0, p.health-damage)
	p.dead = p.health == 0
	s.sendTo(p, M{
		"t": "pvp-health", "id": p.id, "amount": damage, "health": p.health,
		"dead": p.dead, "by": "Custom item effect", "knockX": 0, "knockZ": 0, "knockback": 0,
	})
}

func (s *server) pvpRespawn(p *player) {
	if !s.pvp || !p.dead {
		return
	}
	p.dead, p.health = false, maxHealth
	x, y, z := p.x, p.y, p.z
	if s.spawn != nil {
		x, y, z = s.spawn[0], s.spawn[1], s.spawn[2]
	}
	p.x, p.y, p.z = x, y, z
	s.broadcast(M{"t": "pvp-respawn", "id": p.id, "x": x, "y": y, "z": z}, nil)
}

// ---------------------------------------------------------------- connections

func (s *server) writer(p *player) {
	ping := time.NewTicker(20 * time.Second)
	defer ping.Stop()
	for {
		select {
		case b := <-p.send:
			p.conn.SetWriteDeadline(time.Now().Add(10 * time.Second))
			if err := p.conn.WriteMessage(websocket.TextMessage, b); err != nil {
				p.conn.Close()
				return
			}
		case <-ping.C:
			p.conn.SetWriteDeadline(time.Now().Add(10 * time.Second))
			if err := p.conn.WriteMessage(websocket.PingMessage, nil); err != nil {
				p.conn.Close()
				return
			}
		case <-p.done:
			return
		}
	}
}

func (s *server) handleWS(w http.ResponseWriter, r *http.Request) {
	c, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		return
	}
	c.SetReadLimit(64 * 1024)
	p := &player{conn: c, send: make(chan []byte, 8192), done: make(chan struct{})}
	go s.writer(p)
	defer func() {
		s.drop(p)
		close(p.done)
		c.Close()
	}()

	c.SetReadDeadline(time.Now().Add(15 * time.Second)) // must say hello quickly
	c.SetPongHandler(func(string) error {
		c.SetReadDeadline(time.Now().Add(70 * time.Second))
		return nil
	})
	for {
		_, data, err := c.ReadMessage()
		if err != nil {
			return
		}
		c.SetReadDeadline(time.Now().Add(70 * time.Second))
		var m inMsg
		if json.Unmarshal(data, &m) != nil {
			continue
		}
		s.handle(p, &m)
	}
}

func setAPICORS(w http.ResponseWriter) {
	w.Header().Set("Access-Control-Allow-Origin", "*")
	w.Header().Set("Access-Control-Allow-Headers", "Content-Type, X-Server-Op-Code")
	w.Header().Set("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
	w.Header().Set("Cache-Control", "no-store")
}

func handleFavicon(w http.ResponseWriter, _ *http.Request) {
	w.WriteHeader(http.StatusNoContent)
}

func (s *server) authorizedOperator(code string) bool {
	return s.operatorCode != "" &&
		subtle.ConstantTimeCompare([]byte(code), []byte(s.operatorCode)) == 1
}

func (s *server) checkOperatorCode(r *http.Request, code string) (bool, bool) {
	host, _, err := net.SplitHostPort(r.RemoteAddr)
	if err != nil {
		host = r.RemoteAddr
	}
	now := time.Now()
	s.opMu.Lock()
	defer s.opMu.Unlock()
	if s.opAttempts == nil {
		s.opAttempts = map[string]operatorAttempt{}
	}
	attempt := s.opAttempts[host]
	if now.After(attempt.expires) {
		attempt = operatorAttempt{}
	}
	if attempt.failures >= 8 {
		return false, true
	}
	if s.authorizedOperator(code) {
		delete(s.opAttempts, host)
		return true, false
	}
	if attempt.failures == 0 {
		attempt.expires = now.Add(15 * time.Minute)
	}
	attempt.failures++
	s.opAttempts[host] = attempt
	return false, false
}

func writeAPIError(w http.ResponseWriter, status int, message string) {
	http.Error(w, message, status)
}

func (s *server) handleOperator(w http.ResponseWriter, r *http.Request) {
	setAPICORS(w)
	if r.Method == http.MethodOptions {
		w.WriteHeader(http.StatusNoContent)
		return
	}
	if r.Method != http.MethodPost {
		writeAPIError(w, http.StatusMethodNotAllowed, "Use POST to verify the operator code.")
		return
	}
	if s.operatorCode == "" {
		writeAPIError(w, http.StatusServiceUnavailable, "Server operator access is not configured.")
		return
	}
	r.Body = http.MaxBytesReader(w, r.Body, 4096)
	var request struct {
		Code string `json:"code"`
	}
	if err := json.NewDecoder(r.Body).Decode(&request); err != nil {
		writeAPIError(w, http.StatusBadRequest, "Invalid operator-code request.")
		return
	}
	authorized, blocked := s.checkOperatorCode(r, request.Code)
	if blocked {
		writeAPIError(w, http.StatusTooManyRequests, "Too many incorrect operator-code attempts. Try again later.")
		return
	}
	if !authorized {
		writeAPIError(w, http.StatusUnauthorized, "Incorrect server operator code.")
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func (s *server) handleDefinitions(w http.ResponseWriter, r *http.Request) {
	setAPICORS(w)
	if r.Method == http.MethodOptions {
		w.WriteHeader(http.StatusNoContent)
		return
	}
	switch r.Method {
	case http.MethodGet:
		w.Header().Set("Content-Type", "application/json; charset=utf-8")
		if err := json.NewEncoder(w).Encode(s.activeKindPayloads("definition")); err != nil {
			log.Println("could not return shared definitions:", err)
		}
	case http.MethodPost:
		if s.operatorCode == "" {
			writeAPIError(w, http.StatusServiceUnavailable, "Server operator access is not configured.")
			return
		}
		authorized, blocked := s.checkOperatorCode(r, r.Header.Get("X-Server-Op-Code"))
		if blocked {
			writeAPIError(w, http.StatusTooManyRequests, "Too many incorrect operator-code attempts. Try again later.")
			return
		}
		if !authorized {
			writeAPIError(w, http.StatusUnauthorized, "Server operator access is required.")
			return
		}
		r.Body = http.MaxBytesReader(w, r.Body, 32<<20)
		data, err := io.ReadAll(r.Body)
		if err != nil {
			writeAPIError(w, http.StatusBadRequest, "Definition file is too large or could not be read.")
			return
		}
		var metadata struct {
			Schema   string `json:"schema"`
			Kind     string `json:"kind"`
			Name     string `json:"name"`
			Registry struct {
				ID int `json:"id"`
			} `json:"registry"`
		}
		if err := json.Unmarshal(data, &metadata); err != nil || !json.Valid(data) ||
			(metadata.Schema != "coop1.10.item-block-definition.v1" &&
				metadata.Schema != "coop1.10.item-block-definition.v2") ||
			(metadata.Kind != "tool" && metadata.Kind != "block") ||
			strings.TrimSpace(metadata.Name) == "" || metadata.Registry.ID > 65535 ||
			(metadata.Kind == "block" && metadata.Registry.ID > 255) ||
			(metadata.Kind == "tool" && metadata.Registry.ID < 120) ||
			(metadata.Kind == "block" && (metadata.Registry.ID < 30 ||
				metadata.Registry.ID == 99 || (metadata.Registry.ID >= 100 && metadata.Registry.ID <= 119))) {
			writeAPIError(w, http.StatusBadRequest, "Invalid item/block definition JSON.")
			return
		}
		path := filepath.Join(s.definitionsDir, fmt.Sprintf("%d.json", metadata.Registry.ID))
		s.mu.Lock()
		tmp, err := os.CreateTemp(s.definitionsDir, ".definition-*.tmp")
		if err != nil {
			s.mu.Unlock()
			writeAPIError(w, http.StatusInternalServerError, "Could not save the shared definition.")
			log.Println("could not save shared definition:", err)
			return
		}
		tmpPath := tmp.Name()
		defer os.Remove(tmpPath)
		if _, err = tmp.Write(data); err == nil {
			err = tmp.Close()
		} else {
			_ = tmp.Close()
		}
		if err == nil {
			err = os.Rename(tmpPath, path)
		}
		if err != nil {
			s.mu.Unlock()
			writeAPIError(w, http.StatusInternalServerError, "Could not save the shared definition.")
			log.Println("could not save shared definition:", err)
			return
		}
		if info, ok := inspectMod(data); ok {
			info.File = fmt.Sprintf("%d.json", metadata.Registry.ID)
			info.Path = path
			s.rememberActiveLocked(info)
		}
		s.broadcast(M{"t": "definition", "definition": json.RawMessage(data)}, nil)
		s.mu.Unlock()
		w.WriteHeader(http.StatusNoContent)
	default:
		writeAPIError(w, http.StatusMethodNotAllowed, "Use GET or POST for shared definitions.")
	}
}

func (s *server) handlePacks(w http.ResponseWriter, r *http.Request) {
	setAPICORS(w)
	if r.Method == http.MethodOptions {
		w.WriteHeader(http.StatusNoContent)
		return
	}
	switch r.Method {
	case http.MethodGet:
		w.Header().Set("Content-Type", "application/json; charset=utf-8")
		if err := json.NewEncoder(w).Encode(s.activeKindPayloads("pack")); err != nil {
			log.Println("could not return shared packs:", err)
		}
	case http.MethodPost:
		if s.operatorCode == "" {
			writeAPIError(w, http.StatusServiceUnavailable, "Server operator access is not configured.")
			return
		}
		authorized, blocked := s.checkOperatorCode(r, r.Header.Get("X-Server-Op-Code"))
		if blocked {
			writeAPIError(w, http.StatusTooManyRequests, "Too many incorrect operator-code attempts. Try again later.")
			return
		}
		if !authorized {
			writeAPIError(w, http.StatusUnauthorized, "Server operator access is required.")
			return
		}
		r.Body = http.MaxBytesReader(w, r.Body, 32<<20)
		data, err := io.ReadAll(r.Body)
		if err != nil {
			writeAPIError(w, http.StatusBadRequest, "Pack file is too large or could not be read.")
			return
		}
		var metadata struct {
			Schema     string            `json:"schema"`
			ID         string            `json:"id"`
			Entries    []json.RawMessage `json:"entries"`
			JavaScript struct {
				Runtime string `json:"runtime"`
				Source  string `json:"source"`
			} `json:"javascript"`
		}
		if err := json.Unmarshal(data, &metadata); err != nil || !json.Valid(data) ||
			metadata.Schema != "coop1.10.item-block-pack.v2" ||
			len(metadata.ID) < 1 || len(metadata.ID) > 64 ||
			!sharedPackIDPattern.MatchString(metadata.ID) ||
			len(metadata.Entries) < 1 || len(metadata.Entries) > 256 ||
			metadata.JavaScript.Runtime != "coop1.10.pack-javascript.v1" ||
			len(metadata.JavaScript.Source) > 1<<20 {
			writeAPIError(w, http.StatusBadRequest, "Invalid shared item pack JSON.")
			return
		}
		path := filepath.Join(s.packsDir, metadata.ID+".json")
		s.mu.Lock()
		tmp, err := os.CreateTemp(s.packsDir, ".pack-*.tmp")
		if err != nil {
			s.mu.Unlock()
			writeAPIError(w, http.StatusInternalServerError, "Could not save the shared pack.")
			log.Println("could not save shared pack:", err)
			return
		}
		tmpPath := tmp.Name()
		defer os.Remove(tmpPath)
		if _, err = tmp.Write(data); err == nil {
			err = tmp.Close()
		} else {
			_ = tmp.Close()
		}
		if err == nil {
			err = os.Rename(tmpPath, path)
		}
		if err != nil {
			s.mu.Unlock()
			writeAPIError(w, http.StatusInternalServerError, "Could not save the shared pack.")
			log.Println("could not save shared pack:", err)
			return
		}
		if info, ok := inspectMod(data); ok {
			info.File = metadata.ID + ".json"
			info.Path = path
			s.rememberActiveLocked(info)
		}
		s.broadcast(M{"t": "pack", "pack": json.RawMessage(data)}, nil)
		s.mu.Unlock()
		w.WriteHeader(http.StatusNoContent)
	default:
		writeAPIError(w, http.StatusMethodNotAllowed, "Use GET or POST for shared packs.")
	}
}

func (s *server) handleSettings(w http.ResponseWriter, r *http.Request) {
	setAPICORS(w)
	if r.Method == http.MethodOptions {
		w.WriteHeader(http.StatusNoContent)
		return
	}
	if r.Method == http.MethodGet {
		s.mu.Lock()
		settings := M{"mode": s.mode, "pvp": s.pvp, "time": s.wtime, "pvpKnockback": s.pvpKnockback}
		s.mu.Unlock()
		w.Header().Set("Content-Type", "application/json; charset=utf-8")
		if err := json.NewEncoder(w).Encode(settings); err != nil {
			log.Println("could not return server settings:", err)
		}
		return
	}
	if r.Method != http.MethodPost {
		writeAPIError(w, http.StatusMethodNotAllowed, "Use GET or POST for server settings.")
		return
	}
	if s.operatorCode == "" {
		writeAPIError(w, http.StatusServiceUnavailable, "Server operator access is not configured.")
		return
	}
	authorized, blocked := s.checkOperatorCode(r, r.Header.Get("X-Server-Op-Code"))
	if blocked {
		writeAPIError(w, http.StatusTooManyRequests, "Too many incorrect operator-code attempts. Try again later.")
		return
	}
	if !authorized {
		writeAPIError(w, http.StatusUnauthorized, "Server operator access is required.")
		return
	}
	r.Body = http.MaxBytesReader(w, r.Body, 4096)
	var settings struct {
		Mode         string   `json:"mode"`
		PvP          *bool    `json:"pvp"`
		Time         *float64 `json:"time"`
		PvPKnockback *float64 `json:"pvpKnockback"`
	}
	if err := json.NewDecoder(r.Body).Decode(&settings); err != nil ||
		(settings.Mode != "survival" && settings.Mode != "creative") ||
		settings.PvP == nil || settings.Time == nil || settings.PvPKnockback == nil ||
		math.IsNaN(*settings.Time) || math.IsInf(*settings.Time, 0) ||
		*settings.Time < 0 || *settings.Time >= 1 ||
		math.IsNaN(*settings.PvPKnockback) || math.IsInf(*settings.PvPKnockback, 0) ||
		*settings.PvPKnockback < 0 || *settings.PvPKnockback > 2 {
		writeAPIError(w, http.StatusBadRequest, "Provide a valid mode, PvP setting, time from 0 to 1, and knockback from 0 to 2.")
		return
	}
	s.mu.Lock()
	s.setGameMode(settings.Mode)
	s.setPvP(*settings.PvP)
	s.setWorldTime(*settings.Time)
	s.setPvPKnockback(*settings.PvPKnockback)
	s.mu.Unlock()
	w.WriteHeader(http.StatusNoContent)
}

// ---------------------------------------------------------------- time + persistence

func (s *server) loop() {
	tk := time.NewTicker(time.Second)
	n := 0
	for range tk.C {
		n++
		s.mu.Lock()
		if len(s.players) > 0 {
			s.wtime = math.Mod(s.wtime+1.0/dayLength, 1)
			if n%10 == 0 {
				s.broadcast(M{"t": "tm", "time": s.wtime}, nil)
			}
		}
		s.mu.Unlock()
		if n%30 == 0 {
			s.save(false)
		}
	}
}

func (s *server) save(force bool) {
	s.mu.Lock()
	if !force && !s.dirty {
		s.mu.Unlock()
		return
	}
	knockback := s.pvpKnockback
	sf := saveFile{
		Seed: s.seed, Mode: s.mode, Time: s.wtime, PVP: s.pvp,
		PvPKnockback: &knockback, Spawn: s.spawn, Edits: s.encodeEdits(),
		Fluid: encodeVoxels(s.fluid),
	}
	s.dirty = false
	path := s.savePath
	s.mu.Unlock()

	data, err := json.Marshal(sf)
	if err != nil {
		log.Println("save error:", err)
		return
	}
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, data, 0o644); err != nil {
		log.Println("save error:", err)
		return
	}
	if err := os.Rename(tmp, path); err != nil {
		log.Println("save error:", err)
		return
	}
	log.Printf("world saved (%d edits)", len(sf.Edits)/5)
}

func (s *server) load() bool {
	data, err := os.ReadFile(s.savePath)
	if err != nil {
		return false
	}
	var sf saveFile
	if err := json.Unmarshal(data, &sf); err != nil {
		log.Println("could not read save file:", err)
		return false
	}
	s.seed, s.mode, s.wtime, s.pvp, s.spawn = sf.Seed, sf.Mode, sf.Time, sf.PVP, sf.Spawn
	s.pvpKnockback = defaultPvpKnockback
	if sf.PvPKnockback != nil && !math.IsNaN(*sf.PvPKnockback) &&
		!math.IsInf(*sf.PvPKnockback, 0) && *sf.PvPKnockback >= 0 && *sf.PvPKnockback <= 2 {
		s.pvpKnockback = *sf.PvPKnockback
	}
	for o := 0; o+5 <= len(sf.Edits); o += 5 {
		s.edits[binary.LittleEndian.Uint32(sf.Edits[o:o+4])] = sf.Edits[o+4]
	}
	if s.fluid == nil {
		s.fluid = map[uint32]uint8{}
	}
	for o := 0; o+5 <= len(sf.Fluid); o += 5 {
		if sf.Fluid[o+4] > 0 {
			s.fluid[binary.LittleEndian.Uint32(sf.Fluid[o:o+4])] = sf.Fluid[o+4]
		}
	}
	return true
}

// ---------------------------------------------------------------- ngrok

var ngrokCmd *exec.Cmd

// startNgrok launches the ngrok CLI (must be installed, on PATH, and have an
// authtoken configured) and prints the public https URL it was given.
func startNgrok(port, domain string) {
	args := []string{"http", port, "--log=stderr", "--log-level=warn"}
	if domain != "" {
		args = append(args, "--domain="+domain)
	}
	cmd := exec.Command("ngrok", args...)
	cmd.Stderr = os.Stderr
	if err := cmd.Start(); err != nil {
		log.Println("could not start ngrok (installed and on PATH?):", err)
		return
	}
	ngrokCmd = cmd
	go func() {
		cmd.Wait()
		log.Println("ngrok exited")
	}()

	client := &http.Client{Timeout: 2 * time.Second}
	for i := 0; i < 40; i++ {
		time.Sleep(500 * time.Millisecond)
		resp, err := client.Get("http://127.0.0.1:4040/api/tunnels")
		if err != nil {
			continue
		}
		var out struct {
			Tunnels []struct {
				PublicURL string `json:"public_url"`
			} `json:"tunnels"`
		}
		err = json.NewDecoder(resp.Body).Decode(&out)
		resp.Body.Close()
		if err != nil {
			continue
		}
		for _, t := range out.Tunnels {
			if strings.HasPrefix(t.PublicURL, "https://") {
				log.Printf("  ONLINE:   %s   <- give this link to your friends", t.PublicURL)
				return
			}
		}
	}
	log.Println("ngrok started but no tunnel URL appeared; run `ngrok config check` and make sure your authtoken is set")
}

// ---------------------------------------------------------------- main

func main() {
	defaultAddr := ":8080"
	if port := os.Getenv("PORT"); port != "" {
		defaultAddr = ":" + port
	}
	addr := flag.String("addr", defaultAddr, "listen address")
	seedFlag := flag.Int64("seed", 0, "world seed, integer (0 = random); only used when creating a new world")
	mode := flag.String("mode", "survival", "survival or creative; only used when creating a new world")
	pvp := flag.Bool("pvp", false, "PvP on at start; only used when creating a new world")
	save := flag.String("save", "world.mcsrv.json", "world save file")
	operatorCode := flag.String("op-code", os.Getenv("EZZYCRAFT_OP_CODE"), "server operator code; required to unlock in-game server settings (or set EZZYCRAFT_OP_CODE)")
	modsDir := flag.String("mods-dir", "mods", "folder of committed pack/definition JSON files loaded by filename")
	definitionsDir := flag.String("definitions-dir", filepath.Join("server_data", "definitions"), "legacy folder still searched for shared item/block JSON definitions")
	packsDir := flag.String("packs-dir", filepath.Join("server_data", "packs"), "legacy folder still searched for shared JavaScript pack JSON files")
	useNgrok := flag.Bool("ngrok", false, "start an ngrok tunnel and print the public URL")
	ngrokDomain := flag.String("ngrok-domain", "", "optional reserved ngrok domain, e.g. my-name.ngrok-free.app")
	flag.Parse()

	s := &server{
		edits:          map[uint32]uint8{},
		fluid:          map[uint32]uint8{},
		players:        map[int]*player{},
		drops:          map[uint64]*worldDrop{},
		projectiles:    map[uint64]*worldProjectile{},
		savePath:       *save,
		modsDir:        *modsDir,
		definitionsDir: *definitionsDir,
		packsDir:       *packsDir,
		activePath:     filepath.Join("server_data", "active-mods.json"),
		operatorCode:   *operatorCode,
		pvpKnockback:   defaultPvpKnockback,
		wtime:          startTime,
	}
	if err := os.MkdirAll(s.modsDir, 0o755); err != nil {
		log.Fatal("could not create mods folder: ", err)
	}
	if err := os.MkdirAll(s.definitionsDir, 0o755); err != nil {
		log.Fatal("could not create shared definitions folder: ", err)
	}
	if err := os.MkdirAll(s.packsDir, 0o755); err != nil {
		log.Fatal("could not create shared packs folder: ", err)
	}
	s.loadActiveMods()
	log.Printf("mod catalog: %d files, %d active", len(s.listAvailableMods()), len(s.activeMods))
	if s.operatorCode == "" {
		log.Println("server operator settings are disabled (set -op-code to enable them)")
	}
	if s.load() {
		log.Printf("loaded world from %s (seed %d, %s, %d edits)", s.savePath, s.seed, s.mode, len(s.edits))
	} else {
		s.seed = int32(*seedFlag)
		if s.seed == 0 {
			s.seed = rand.Int31()
		}
		s.mode = "survival"
		if *mode == "creative" {
			s.mode = "creative"
		}
		s.pvp = *pvp
		s.dirty = true
		log.Printf("new world (seed %d, %s)", s.seed, s.mode)
	}

	go s.loop()

	sig := make(chan os.Signal, 1)
	signal.Notify(sig, os.Interrupt, syscall.SIGTERM)
	go func() {
		<-sig
		log.Println("shutting down, saving world...")
		s.save(true)
		if ngrokCmd != nil && ngrokCmd.Process != nil {
			ngrokCmd.Process.Kill()
		}
		os.Exit(0)
	}()

	http.HandleFunc("/ws", s.handleWS)
	http.HandleFunc("/api/operator", s.handleOperator)
	http.HandleFunc("/api/definitions", s.handleDefinitions)
	http.HandleFunc("/api/packs", s.handlePacks)
	http.HandleFunc("/api/mods", s.handleMods)
	http.HandleFunc("/api/settings", s.handleSettings)
	http.HandleFunc("/favicon.ico", handleFavicon)
	http.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/" {
			http.NotFound(w, r)
			return
		}
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		w.Header().Set("Cache-Control", "no-cache")
		w.Write(indexHTML)
	})

	_, port, err := net.SplitHostPort(*addr)
	if err != nil {
		port = "8080"
	}
	log.Printf("listening on %s", *addr)
	log.Printf("  this PC:  http://localhost:%s", port)
	if addrs, err := net.InterfaceAddrs(); err == nil {
		for _, a := range addrs {
			if ipn, ok := a.(*net.IPNet); ok && !ipn.IP.IsLoopback() && ipn.IP.To4() != nil {
				log.Printf("  LAN:      http://%s:%s", ipn.IP, port)
			}
		}
	}
	if *useNgrok {
		go startNgrok(port, *ngrokDomain)
	}
	log.Fatal(http.ListenAndServe(*addr, nil))
}
